from collections import deque
def fill_enclosed(grid, fill=4):
    h,w=len(grid),len(grid[0])
    bg=max(set(v for r in grid for v in r), key=lambda c: sum(r.count(c) for r in grid))
    seen=[[False]*w for _ in range(h)]; dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for a,b in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
            if 0<=a<h and 0<=b<w and grid[a][b]==bg and not seen[a][b]: seen[a][b]=True; dq.append((a,b))
    return [[fill if grid[i][j]==bg and not seen[i][j] else grid[i][j] for j in range(w)] for i in range(h)]
